<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../api/client';const items=ref<any[]>([]),permissions=ref<any[]>([]),show=ref(false),form=ref({name:'',description:'',permission_ids:[] as string[]});async function load(){const[r,p]=await Promise.all([api.get('/roles'),api.get('/permissions')]);items.value=r.data.items||[];permissions.value=(p.data.groups||[]).flatMap((x:any)=>x.Permissions||[])}async function create(){await api.post('/roles',form.value);show.value=false;await load()}async function assign(x:any){const ids=prompt('请输入权限 ID，多个用逗号分隔',(x.Permissions||[]).map((p:any)=>p.ID).join(','));if(ids!==null){await api.put(`/roles/${x.ID}/permissions`,{permission_ids:ids.split(',').map(v=>v.trim()).filter(Boolean)});await load()}}onMounted(load)</script>
<template><div class="page"><div class="page-title"><div><h1>角色管理</h1><p>角色是权限集合，后端会对每个受保护 API 进行校验</p></div><button class="primary-button" @click="show=true">＋ 新增角色</button></div><section class="card"><table class="data-table"><thead><tr><th>角色</th><th>说明</th><th>用户数</th><th>权限数</th><th>类型</th><th>操作</th></tr></thead><tbody><tr v-for="x in items" :key="x.ID"><td><strong>{{x.Name}}</strong></td><td>{{x.Description}}</td><td>{{x.UserCount}}</td><td>{{(x.Permissions||[]).length}}</td><td>{{x.BuiltIn?'内置':'自定义'}}</td><td><button class="secondary-button" @click="assign(x)">配置权限</button></td></tr></tbody></table></section><div v-if="show" class="modal-mask" @click.self="show=false"><div class="modal"><div class="modal-header"><h3>新增角色</h3><button class="close-button" @click="show=false">×</button></div><div class="modal-body"><div class="form-grid"><label><span>角色编码</span><input v-model="form.name"></label><label><span>角色说明</span><input v-model="form.description"></label><label class="full"><span>初始权限</span><select v-model="form.permission_ids" multiple><option v-for="p in permissions" :key="p.ID" :value="p.ID">{{p.Code}} · {{p.Description}}</option></select></label></div></div><div class="modal-footer"><button class="secondary-button" @click="show=false">取消</button><button class="primary-button" @click="create">创建</button></div></div></div></div></template>
